const mlx = (model) => {
  if (model.pipeline_tag === "image-text-to-text") {
    return mlxvlm(model);
  }
  if (model.pipeline_tag === "text-generation") {
    if (model.tags.includes("conversational")) {
      return mlxchat(model);
    } else {
      return mlxlm(model);
    }
  }
  return mlx_unknown(model);
};
